import{_ as a,o as t,c as r,ae as o}from"./chunks/framework.Dn7Y7LSn.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"reference/faq.md","filePath":"reference/faq.md"}'),s={name:"reference/faq.md"};function i(n,e,h,l,d,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="is-orchestra-free" tabindex="-1">Is Orchestra free? <a class="header-anchor" href="#is-orchestra-free" aria-label="Permalink to &quot;Is Orchestra free?&quot;">​</a></h2><p>Yes, Orchestra is completely free and open source.</p><h2 id="does-it-send-my-data-anywhere" tabindex="-1">Does it send my data anywhere? <a class="header-anchor" href="#does-it-send-my-data-anywhere" aria-label="Permalink to &quot;Does it send my data anywhere?&quot;">​</a></h2><p>No. All data stays on your local machine. The hook server runs on <code>localhost:3008</code> and only accepts connections from your local Claude Code sessions. No data is sent to any external server.</p><h2 id="which-ai-coding-agents-are-supported" tabindex="-1">Which AI coding agents are supported? <a class="header-anchor" href="#which-ai-coding-agents-are-supported" aria-label="Permalink to &quot;Which AI coding agents are supported?&quot;">​</a></h2><p>Currently, Orchestra supports <strong>Claude Code</strong> via its Hooks system. Support for additional agents may be added in the future.</p><h2 id="what-are-the-system-requirements" tabindex="-1">What are the system requirements? <a class="header-anchor" href="#what-are-the-system-requirements" aria-label="Permalink to &quot;What are the system requirements?&quot;">​</a></h2><ul><li>macOS 11.0+ (Big Sur or later)</li><li>Apple Silicon (M1/M2/M3/M4)</li><li>tmux (for session jumping)</li><li>Claude Code installed</li></ul><h2 id="how-do-i-uninstall-orchestra" tabindex="-1">How do I uninstall Orchestra? <a class="header-anchor" href="#how-do-i-uninstall-orchestra" aria-label="Permalink to &quot;How do I uninstall Orchestra?&quot;">​</a></h2><ol><li>Quit Orchestra if it&#39;s running</li><li>Delete <code>Orchestra.app</code> from <code>/Applications</code></li><li>Remove the hook configuration from <code>~/.claude/settings.json</code></li></ol><h2 id="can-i-use-orchestra-without-tmux" tabindex="-1">Can I use Orchestra without tmux? <a class="header-anchor" href="#can-i-use-orchestra-without-tmux" aria-label="Permalink to &quot;Can I use Orchestra without tmux?&quot;">​</a></h2><p>Orchestra will still monitor your sessions without tmux, but the &quot;Jump to session&quot; feature requires tmux to work. Sessions running outside tmux will appear in the dashboard but won&#39;t have a Jump button.</p><h2 id="does-orchestra-work-with-claude-code-teams" tabindex="-1">Does Orchestra work with Claude Code teams? <a class="header-anchor" href="#does-orchestra-work-with-claude-code-teams" aria-label="Permalink to &quot;Does Orchestra work with Claude Code teams?&quot;">​</a></h2><p>Yes. Orchestra monitors all hook events from any Claude Code session on your machine, including team sessions and subagent activity.</p>',15)])])}const p=a(s,[["render",i]]);export{m as __pageData,p as default};
